def next_smallest_palindrome(n: int) -> int:
    s = str(n)
    length = len(s)

    # If all digits are 9, the next palindrome is 10...01 (length+1)
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    def mirror_left_to_right(x: str) -> str:
        half = length // 2
        if length % 2 == 0:
            return x[:half] + x[:half][::-1]
        else:
            return x[:half+1] + x[:half][::-1]

    # Start from n+1 because we want strictly greater palindrome
    candidate = n + 1
    while True:
        s = str(candidate)
        length = len(s)

        # If length changed due to increment (like 999 -> 1000), handle separately
        if length != len(str(candidate - 1)):
            # If new length, check if all 9’s case handled above
            # Just try mirror approach again
            pass

        # Construct palindrome by mirroring left to right
        left_part = s[:length // 2]
        middle = s[length // 2] if length % 2 else ''
        if length % 2 == 0:
            pal = left_part + left_part[::-1]
        else:
            pal = left_part + middle + left_part[::-1]

        pal_num = int(pal)
        if pal_num >= candidate:
            return pal_num
        else:
            # If palindrome formed is smaller than candidate,
            # increment the middle part and mirror again
            if length % 2 == 0:
                # even length
                left_int = int(left_part)
                left_int += 1
                left_str = str(left_int)
                # if increment causes length increase (e.g. 99 -> 100)
                if len(left_str) > len(left_part):
                    # length increased, so palindrome length increased
                    # next palindrome is 10...01 with length+1
                    return int('1' + ('0' * (length - 1)) + '1')
                pal = left_str + left_str[::-1]
                return int(pal)
            else:
                # odd length
                left_plus_mid = s[:(length // 2) + 1]
                left_plus_mid_int = int(left_plus_mid)
                left_plus_mid_int += 1
                left_plus_mid_str = str(left_plus_mid_int)
                if len(left_plus_mid_str) > len(left_plus_mid):
                    # length increased, palindrome length increased
                    return int('1' + ('0' * (length - 1)) + '1')
                left_part_new = left_plus_mid_str[:-1]
                middle_new = left_plus_mid_str[-1]
                pal = left_part_new + middle_new + left_part_new[::-1]
                return int(pal)

from decimal import Decimal, InvalidOperation

def is_decimal(value) -> bool:
    try:
        d = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return False
    # Normalize to remove trailing zeros without changing precision
    tup = d.as_tuple()
    # Number of digits after decimal point = -exponent if exponent negative, else 0
    return -tup.exponent == 2

