def parse_music(music_string: str) -> List[int]:
    notes = music_string.split()
    result = []
    for note in notes:
        if note == 'o':
            result.append(1)  # whole note lasts 1 beat
        elif note == 'o|':
            result.append(4)  # half note lasts 4 beats
        elif note == '.|':
