        else:
            raise ValueError(f"Unknown note format: {note}")
    return result

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    shift %= n
    if shift == 0:
        return s
    # Positive shift means right rotation
    return s[-shift:] + s[:-shift]

